  <?php foreach($resultDetails as $cardIndex=>$detail): $structured=(($detail['ResultMode']??'')==='Structured Parameters') && !empty($detail['parameters']) && (int)($detail['parameters'][0]['ParameterID']??0)>0; $single=(!$structured && !empty($detail['parameters']))?$detail['parameters'][0]:null; ?><section class="lab-modal-test"><div class="lab-modal-test-head"><div><span class="test-number">Test <?= $cardIndex+1 ?></span><h3><?= tdc_e((string)$detail['ModernTestNameSnapshot']) ?></h3><div class="lab-modal-test-meta"><?= tdc_e((string)($detail['ResultMode']??'Single Result')) ?> · <?= tdc_e((string)($detail['TypeName']??'')) ?></div></div><span class="result-status-badge"><?= tdc_e((string)($detail['ResultStatus']?:'Processing')) ?></span></div>
   <?php if($structured): foreach($detail['parameters'] as $pi=>$parameter): $fi=$cardIndex.'_'.$pi; ?><div class="lab-modal-fields"><div><input type="hidden" name="ParameterID[]" value="<?= (int)($parameter['ParameterID']??0) ?>"><label for="lmv-<?= $fi ?>"><?= tdc_e((string)($parameter['ParameterName']??'Result')) ?><?= !empty($parameter['IsRequired'])?' *':'' ?></label><input id="lmv-<?= $fi ?>" name="ResultValue[]" type="<?= (($parameter['ResultType']??'')==='Numeric')?'number':'text' ?>" <?= (($parameter['ResultType']??'')==='Numeric')?'step="any"':'' ?> value="<?= tdc_e((string)($parameter['RawResult']??'')) ?>"><small><?= tdc_e(implode(' · ',array_filter([$parameter['UnitName']??'',$parameter['ReferenceRange']??'',$parameter['FlagCodeSnapshot']??'']))) ?></small></div><div><label for="lmr-<?= $fi ?>">Remark</label><textarea id="lmr-<?= $fi ?>" name="Remark[]" rows="2"><?= tdc_e((string)($parameter['Remark']??'')) ?></textarea></div></div><?php endforeach; else: $rid=(int)($detail['LabResultID']??0); ?><div class="lab-modal-fields"><div><label for="lms-<?= $cardIndex ?>">Result *</label><input id="lms-<?= $cardIndex ?>" name="SingleResult[<?= $rid ?>]" value="<?= tdc_e((string)($single['RawResult']??'')) ?>"></div><div><label for="lmt-<?= $cardIndex ?>">Remark</label><textarea id="lmt-<?= $cardIndex ?>" name="SingleRemark[<?= $rid ?>]" rows="2"><?= tdc_e((string)($single['Remark']??'')) ?></textarea></div></div><?php endif; ?></section><?php endforeach; ?>
